using OpenTelemetry.Metrics; using System; namespace KKBOT.Observability.Metrics; public sealed class MetricsRegistry : IDisposable { private readonly Meter _meter; public Counter<long> InstancesTotal { get; } public Counter<long> JobsRunning { get; } public MetricsRegistry() { _meter = new Meter("KKBOT", "1.0.0"); InstancesTotal = _meter.CreateCounter<long>(MetricNames.InstancesTotal); JobsRunning = _meter.CreateCounter<long>(MetricNames.JobsRunning); } public void Dispose() => _meter?.Dispose(); }